CREATE TABLE radar_kv (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE radar_movies (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE radar_stars (movie_id TEXT PRIMARY KEY, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE radar_sessions (id TEXT PRIMARY KEY, movie_id TEXT NOT NULL, available INTEGER NOT NULL, generation INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE radar_events (id TEXT PRIMARY KEY, movie_id TEXT, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL, sent_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0, next_try INTEGER NOT NULL DEFAULT 0, cancelled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE radar_lock (id INTEGER PRIMARY KEY, expires INTEGER NOT NULL);
